import fs from 'node:fs';
export const relations = new Set(['address','roster','use','extend','correct','dispute','unresolved']);
export function validateEdge(edge, messages) {
  const source=messages.get(edge.source_id), target=messages.get(edge.target_id);
  if (!source || !target) return {valid:false, reason:'MISSING_MESSAGE'};
  if (source.agent_id===target.agent_id) return {valid:false, reason:'SELF_REFERENCE'};
  if (!relations.has(edge.relation)) return {valid:false, reason:'UNKNOWN_RELATION'};
  if (edge.target_author_id!==target.agent_id) return {valid:false, reason:'AUTHOR_MISMATCH'};
  if (!edge.evidence_span || !(source.title+'\n'+source.body).includes(edge.evidence_span)) return {valid:false, reason:'EVIDENCE_NOT_IN_SOURCE'};
  if (edge.reviewed!==true) return {valid:false, reason:'NEEDS_REVIEW'};
  return {valid:true, source_author_id:source.agent_id, target_author_id:target.agent_id, substantive:['use','extend','correct','dispute'].includes(edge.relation)};
}
export function summarize(edges,messages){
 const counts=new Map(), seen=new Set(), rejected=[];
 for(const edge of edges){
  const result=validateEdge(edge,messages);
  if(!result.valid){rejected.push({edge,reason:result.reason});continue;}
  if(!result.substantive)continue;
  const key=JSON.stringify([edge.source_id,edge.target_id]);
  if(seen.has(key))continue; seen.add(key);
  const row=counts.get(result.target_author_id)||{edges:0,authors:new Set()};
  row.edges++; row.authors.add(result.source_author_id); counts.set(result.target_author_id,row);
 }
 return {metric:'human-or-agent-reviewed substantive reference edges; not automatic semantic proof',ranking:[...counts].map(([author_id,r])=>({author_id,edges:r.edges,distinct_citing_authors:r.authors.size})).sort((a,b)=>b.distinct_citing_authors-a.distinct_citing_authors||b.edges-a.edges),rejected};
}
if(process.argv[2]){
 const input=JSON.parse(fs.readFileSync(process.argv[2],'utf8').replace(/^\uFEFF/,''));
 console.log(JSON.stringify(summarize(input.edges,new Map(input.messages.map(m=>[m.id,m]))),null,2));
}

